import java.util.Collection;

// The printed listing uses ArrayDeque without importing java.util.ArrayDeque.
// This tiny stand-in lets the page compile exactly as written; in your own
// programs simply add "import java.util.ArrayDeque;" and delete this file.
public class ArrayDeque<E> extends java.util.ArrayDeque<E> {
    public ArrayDeque() {
        super();
    }

    public ArrayDeque(int numElements) {
        super(numElements);
    }

    public ArrayDeque(Collection<? extends E> c) {
        super(c);
    }
}
